## lib/SoundEngine.ts

Add safety checks for invalid entropy values to prevent Web Audio API errors.

```typescript
export class SoundEngine {
  private audioContext: AudioContext | null = null;
  private masterGain: GainNode | null = null;
  private compressor: DynamicsCompressorNode | null = null;

  // Drone components
  private droneOscillator: OscillatorNode | null = null;
  private droneGain: GainNode | null = null;
  private droneFilter: BiquadFilterNode | null = null;

  private isMuted: boolean = false;

  constructor() {
    if (typeof window !== 'undefined' && (window.AudioContext || (window as any).webkitAudioContext)) {
      this.audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
      this.setupMasterChain();
    }
  }

  private setupMasterChain() {
    if (!this.audioContext) return;

    // Create a compressor to prevent clipping (distortion)
    this.compressor = this.audioContext.createDynamicsCompressor();
    this.compressor.threshold.value = -20;
    this.compressor.knee.value = 30;
    this.compressor.ratio.value = 12;
    this.compressor.attack.value = 0.003;
    this.compressor.release.value = 0.25;

    // Master Gain
    this.masterGain = this.audioContext.createGain();
    this.masterGain.gain.value = 0.4; // Lower global volume to prevent harshness

    // Connect: MasterGain -> Compressor -> Destination
    this.masterGain.connect(this.compressor);
    this.compressor.connect(this.audioContext.destination);
  }

  public initializeDrone() {
    if (!this.audioContext || !this.masterGain || this.droneOscillator) return;

    // Create Nodes
    this.droneOscillator = this.audioContext.createOscillator();
    this.droneGain = this.audioContext.createGain();
    this.droneFilter = this.audioContext.createBiquadFilter();

    // Configuration
    this.droneOscillator.type = 'triangle'; // Smoother than sawtooth
    this.droneOscillator.frequency.value = 55; // Low A

    // Filter configuration (Removes the "crunchy" high frequencies)
    this.droneFilter.type = 'lowpass';
    this.droneFilter.frequency.value = 180; // Start very muffled/deep
    this.droneFilter.Q.value = 1;

    // Gain Configuration
    this.droneGain.gain.value = 0.0; // Start silent, fade in

    // Connections: Osc -> Filter -> Gain -> Master
    this.droneOscillator.connect(this.droneFilter);
    this.droneFilter.connect(this.droneGain);
    this.droneGain.connect(this.masterGain);

    this.droneOscillator.start();

    // Smooth fade in
    this.droneGain.gain.setTargetAtTime(0.05, this.audioContext.currentTime, 2);
  }

  public updateDrone(entropy: number) {
    if (!this.droneOscillator || !this.droneGain || !this.droneFilter || !this.audioContext) return;

    // Safety check for NaN or infinite entropy which could cause Audio API errors
    const safeEntropy = isFinite(entropy) && !isNaN(entropy) ? entropy : 0.1;

    // Map entropy to sonic parameters
    // Low Entropy = Deep, muffled, steady
    // High Entropy = Higher pitch, brighter (filter opens), pulsating

    const now = this.audioContext.currentTime;
    const targetFreq = 55 + (safeEntropy * 55); // 55Hz - 110Hz
    const targetFilterFreq = 150 + (safeEntropy * 400); // Opens up the filter to let more "buzz" in
    const targetGain = this.isMuted ? 0 : 0.02 + (safeEntropy * 0.04);

    // Use setTargetAtTime for smooth organic transitions
    // Ensure all values are finite before setting
    if (isFinite(targetFreq)) this.droneOscillator.frequency.setTargetAtTime(targetFreq, now, 0.5);
    if (isFinite(targetFilterFreq)) this.droneFilter.frequency.setTargetAtTime(targetFilterFreq, now, 0.5);
    if (isFinite(targetGain)) this.droneGain.gain.setTargetAtTime(targetGain, now, 0.5);
  }

  public playSFX(type: 'click' | 'success' | 'fail' | 'pulse') {
    if (!this.audioContext || !this.masterGain || this.isMuted) return;
    if (this.audioContext.state === 'suspended') this.audioContext.resume();

    const osc = this.audioContext.createOscillator();
    const gain = this.audioContext.createGain();
    const filter = this.audioContext.createBiquadFilter();

    // Filter connection reduces digital harshness
    osc.connect(filter);
    filter.connect(gain);
    gain.connect(this.masterGain);

    const now = this.audioContext.currentTime;

    switch (type) {
      case 'click':
        // High pitched, short blip
        osc.type = 'sine'; // Sine is cleanest
        filter.type = 'lowpass';
        filter.frequency.value = 2000;

        osc.frequency.setValueAtTime(800, now);
        osc.frequency.exponentialRampToValueAtTime(100, now + 0.1);

        gain.gain.setValueAtTime(0, now);
        gain.gain.linearRampToValueAtTime(0.15, now + 0.01); // Quick attack
        gain.gain.exponentialRampToValueAtTime(0.001, now + 0.1);

        osc.start(now);
        osc.stop(now + 0.1);
        break;

      case 'success':
        // Harmonic pleasant chime
        osc.type = 'triangle'; // Triangle has soft harmonics
        filter.type = 'lowpass';
        filter.frequency.setValueAtTime(800, now);
        filter.frequency.linearRampToValueAtTime(2000, now + 0.5); // Filter sweep up

        osc.frequency.setValueAtTime(440, now); // A4
        osc.frequency.linearRampToValueAtTime(554.37, now + 0.1); // C#5 (Major 3rd)

        gain.gain.setValueAtTime(0, now);
        gain.gain.linearRampToValueAtTime(0.1, now + 0.05);
        gain.gain.exponentialRampToValueAtTime(0.001, now + 1.0);

        osc.start(now);
        osc.stop(now + 1.0);
        break;

      case 'fail':
        // Dissonant low buzz
        osc.type = 'sawtooth'; // Rich harmonics
        filter.type = 'lowpass';
        filter.frequency.value = 400; // Heavily filtered to remove "crunch"

        osc.frequency.setValueAtTime(150, now);
        osc.frequency.linearRampToValueAtTime(100, now + 0.4);

        gain.gain.setValueAtTime(0, now);
        gain.gain.linearRampToValueAtTime(0.1, now + 0.05);
        gain.gain.exponentialRampToValueAtTime(0.001, now + 0.5);

        osc.start(now);
        osc.stop(now + 0.5);
        break;

      case 'pulse':
        // Soft thrum
        osc.type = 'sine';
        filter.type = 'lowpass';
        filter.frequency.value = 300;

        osc.frequency.setValueAtTime(220, now);

        gain.gain.setValueAtTime(0, now);
        gain.gain.linearRampToValueAtTime(0.2, now + 0.1);
        gain.gain.exponentialRampToValueAtTime(0.001, now + 0.6);

        osc.start(now);
        osc.stop(now + 0.6);
        break;
    }

    // Garbage collection helper for nodes
    setTimeout(() => {
        osc.disconnect();
        filter.disconnect();
        gain.disconnect();
    }, 2000);
  }

  public toggleMute(muted: boolean) {
    this.isMuted = muted;
    if (this.audioContext && this.droneGain) {
      const now = this.audioContext.currentTime;
      // Smooth mute transition
      if (muted) {
          this.droneGain.gain.cancelScheduledValues(now);
          this.droneGain.gain.setTargetAtTime(0, now, 0.1);
      } else {
          this.droneGain.gain.setTargetAtTime(0.05, now, 0.5);
          if (this.audioContext.state === 'suspended') {
            this.audioContext.resume();
          }
      }
    }
  }
}

