```tsx
import React, { useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';

interface PanelModalProps {
  isOpen: boolean;
  onClose: () => void;
  title: string;
  children: React.ReactNode;
  width?: number | string;
  height?: number | string;
}

const PanelModal: React.FC<PanelModalProps> = ({
  isOpen,
  onClose,
  title,
  children,
  width = '90%',
  height = '85vh',
}) => {
  const modalRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleEscape = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    if (isOpen) {
      document.addEventListener('keydown', handleEscape);
      document.body.style.overflow = 'hidden'; // Prevent background scroll
    }
    return () => {
      document.removeEventListener('keydown', handleEscape);
      document.body.style.overflow = 'unset';
    };
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  // Mobile check (basic)
  const isMobile = typeof window !== 'undefined' && window.innerWidth < 768;

  // Z-Index 5000 ensures it is above the Header (z-50) and Mobile Nav (z-50)
  return createPortal(
    <div className="fixed inset-0 z-[5000] flex items-center justify-center bg-black/90 backdrop-blur-md animate-fade-in-up">
      <div 
        className="absolute inset-0" 
        onClick={onClose} 
        aria-label="Close modal backdrop" 
      />
      <div 
        ref={modalRef}
        className="relative bg-slate-950 border border-slate-700 rounded-xl shadow-2xl flex flex-col overflow-hidden ring-1 ring-white/10"
        style={{ 
            width: isMobile ? '100%' : width, 
            height: isMobile ? '100%' : height, 
            maxWidth: isMobile ? '100%' : '1200px',
            borderRadius: isMobile ? '0' : '0.75rem' // Remove radius on full screen mobile
        }}
        role="dialog"
        aria-modal="true"
        aria-labelledby="modal-title"
      >
        {/* Header */}
        <div className="flex items-center justify-between px-4 py-3 border-b border-slate-700 bg-slate-900 shrink-0">
          <h2 id="modal-title" className="text-lg font-['Cinzel'] font-bold text-slate-100 flex items-center gap-2 truncate pr-2">
            <i className="ri-layout-grid-fill text-indigo-500"></i>
            {title}
          </h2>
          <button 
            onClick={onClose}
            className="p-2 rounded-full text-slate-400 hover:text-white hover:bg-slate-700 transition-colors bg-slate-800/50"
            aria-label="Close modal"
          >
            <i className="ri-close-line text-2xl"></i>
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-auto custom-scrollbar bg-slate-950/50 p-2 md:p-4 flex justify-center w-full">
            {children}
        </div>
      </div>
    </div>,
    document.body
  );
};

export default PanelModal;
