  // Chat State
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [chatInput, setChatInput] = useState("");

  // Leaderboard State
  const [leaderboardData, setLeaderboardData] = useState<LeaderboardEntry[]>([]);

  // Live Feed State
  const [liveFeed, setLiveFeed] = useState<string[]>([]);

  const [isResonating, setIsResonating] = useState(false);
  const particlesRef = useRef<Particle[]>([]);
  const animationFrameIdRef = useRef<number | null>(null);

  // Initialize Mock Data
  useEffect(() => {
      // Initial Chat
      const initialChat: ChatMessage[] = Array.from({length: 8}).map((_, i) => ({
          id: `msg-init-${i}`,
          sender: MOCK_USERNAMES[Math.floor(Math.random() * MOCK_USERNAMES.length)],
          faction: Object.values(AgentFaction)[Math.floor(Math.random() * 8)],
          message: MOCK_CHAT_MESSAGES[Math.floor(Math.random() * MOCK_CHAT_MESSAGES.length)],
          timestamp: Date.now() - (10000 * i)
      })).reverse();
      setChatHistory(initialChat);

      // Initial Leaderboard
      const initialLeaderboard: LeaderboardEntry[] = Array.from({length: 10}).map((_, i) => ({
          id: `lb-${i}`,
          rank: i + 1,
          name: MOCK_USERNAMES[i % MOCK_USERNAMES.length] + `_${Math.floor(Math.random()*100)}`,
          faction: Object.values(AgentFaction)[Math.floor(Math.random() * 8)],
          fluxContribution: 15000 - (i * 1200) + Math.floor(Math.random()*500),
          achievements: ['Void-Touched', 'Star-Forged'],
          avatarSeed: `avatar-${i}`
      }));
      setLeaderboardData(initialLeaderboard);
  }, []);

  // Chat Simulation Loop
  useEffect(() => {
    const interval = setInterval(() => {
        if (Math.random() > 0.6) {
            const newMsg: ChatMessage = {
                id: `msg-${Date.now()}`,
                sender: MOCK_USERNAMES[Math.floor(Math.random() * MOCK_USERNAMES.length)],
                faction: Object.values(AgentFaction)[Math.floor(Math.random() * 8)],
                message: MOCK_CHAT_MESSAGES[Math.floor(Math.random() * MOCK_CHAT_MESSAGES.length)],
                timestamp: Date.now()
            };
            setChatHistory(prev => [...prev.slice(-40), newMsg]);

            // Add to live feed occasionally
            if (Math.random() > 0.7) {
                setLiveFeed(prev => [`${newMsg.sender} transmitted a resonance code.`, ...prev.slice(0, 2)]);
            }
        }
    }, 3500);
    return () => clearInterval(interval);
  }, []);

  // Auto-scroll chat
  useEffect(() => {
    if (activeTab === 'chat' && chatEndRef.current) {
        chatEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [chatHistory, activeTab]);

  const handleSendMessage = (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!chatInput.trim()) return;

    const userMsg: ChatMessage = {
        id: `msg-user-${Date.now()}`,
        sender: "You",
        faction: seekerFaction,
        message: chatInput,
        timestamp: Date.now()
    };
    setChatHistory(prev => [...prev.slice(-40), userMsg]);
    setChatInput("");
  };

  const handleResonate = () => {
    setIsResonating(true);
    // Simulate contribution
    setActiveGoal(prev => ({ ...prev, currentFlux: prev.currentFlux + 100 }));
    // Add visual flare
    if (canvasRef.current) {
        const rect = canvasRef.current.getBoundingClientRect();
        const centerX = rect.width / 2;
        const centerY = rect.height / 2;
        for (let i = 0; i < 20; i++) {
            particlesRef.current.push({
                x: centerX, y: centerY,
                vx: (Math.random() - 0.5) * 10,
                vy: (Math.random() - 0.5) * 10,
                life: 60, baseLife: 60,
                size: Math.random() * 3 + 1,
                color: FACTION_COLORS[seekerFaction] || '#ffffff',
                history: [], type: 'flux_burst'
            });
        }
    }

    setTimeout(() => setIsResonating(false), 200);
    addEchoMessage(
        AgentName.CommunityResonanceAgent, 
        `Flux Contributed (+100). Faction: ${seekerFaction}. Goal Progress: ${((activeGoal.currentFlux/activeGoal.targetFlux)*100).toFixed(2)}%`, 
        'text-cyan-300'
    );
    setLiveFeed(prev => [`You contributed 100 Flux to the Global Goal.`, ...prev.slice(0, 2)]);
  };

  // Canvas Animation (Globe)
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Use resize observer for robust sizing or just parent dimensions
    const parent = canvas.parentElement;
    if (parent) {
        canvas.width = parent.clientWidth;
        canvas.height = parent.clientHeight;
    }

    const render = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      const centerX = canvas.width / 2;
      const centerY = canvas.height / 2;

      // Draw "Globe" / Network
      const time = Date.now() * 0.001;

      // Outer Ring
      ctx.strokeStyle = 'rgba(56, 189, 248, 0.2)'; // sky-400
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.arc(centerX, centerY, canvas.height * 0.4, 0, Math.PI * 2);
      ctx.stroke();

      // Rotating inner rings
      ctx.save();
      ctx.translate(centerX, centerY);
      ctx.rotate(time * 0.2);
      ctx.strokeStyle = 'rgba(168, 85, 247, 0.3)'; // purple-500
      ctx.beginPath();
      ctx.ellipse(0, 0, canvas.height * 0.35, canvas.height * 0.15, 0, 0, Math.PI * 2);
      ctx.stroke();
      ctx.rotate(Math.PI / 2);
      ctx.beginPath();
      ctx.ellipse(0, 0, canvas.height * 0.35, canvas.height * 0.15, 0, 0, Math.PI * 2);
      ctx.stroke();
      ctx.restore();

      // Draw simulated other users (dots on the globe)
      const numDots = 24;
      for (let i = 0; i < numDots; i++) {
          const angle = time * 0.5 + (i * Math.PI * 2 / numDots);
          const orbitRadiusX = canvas.height * 0.35;
          const orbitRadiusY = canvas.height * 0.1;

          // 3D effect simulation
          const yOffset = Math.sin(angle) * orbitRadiusY;
          const scale = (Math.sin(angle + Math.PI/2) + 2) / 3; // 0.33 to 1
          const alpha = scale * scale;

          const x = centerX + Math.cos(angle) * orbitRadiusX;
          const y = centerY + yOffset;

          ctx.fillStyle = `rgba(100, 255, 200, ${alpha})`;
          ctx.beginPath();
          ctx.arc(x, y, 2 * scale, 0, Math.PI * 2);
          ctx.fill();
      }

      // Process Particles (Use reverse loop for safe removal)
      for (let i = particlesRef.current.length - 1; i >= 0; i--) {
          const p = particlesRef.current[i];
          p.x += p.vx;
          p.y += p.vy;
          p.life--;

          if (p.life <= 0) {
            particlesRef.current.splice(i, 1);
            continue;
          }

          ctx.fillStyle = p.color;
          ctx.globalAlpha = p.life / (p.baseLife || 60);
          ctx.beginPath();
          ctx.arc(p.x, p.y, p.size || 2, 0, Math.PI*2);
          ctx.fill();
          ctx.globalAlpha = 1.0;
      }

      animationFrameIdRef.current = requestAnimationFrame(render);
    };
    render();
    return () => {
        if (animationFrameIdRef.current) cancelAnimationFrame(animationFrameIdRef.current);
    };
  }, [width, height, activeTab]); 

  const panelStyle = {
      width: typeof width === 'number' ? `${width}px` : width,
      minHeight: typeof height === 'number' ? `${height}px` : height,
  };

  return (
