```tsx
import React, { useState, useCallback, useMemo } from 'react';
import type { SeekerProfileWeaverPanelProps, SeekerProfile } from '../../types';
import { AgentName, SeekerAvatarType, HistoricalEventType, SeekerGender, SeekerEnergyAlignment, SeekerClass, SeekerAuraColor, SeekerVisualFilter } from '../../types';
import { AGENT_PROFILES, AVATAR_RACES, TRAIT_LISTS, ALL_GENDERS_LIST, ALL_ALIGNMENTS_LIST, SEEKER_CLASSES, SEEKER_AURA_OPTIONS, SEEKER_VISUAL_FILTERS } from '../../constants';
import { useGemini } from '../../context/GeminiIntegrationContext';
import { Button } from '../ui/Button';

const SeekerProfileWeaverPanel: React.FC<SeekerProfileWeaverPanelProps> = ({ addEchoMessage, onProfileCreated, width, height }) => {
  const [step, setStep] = useState<number>(1);
  const [seekerName, setSeekerName] = useState("");
  const [selectedRaceId, setSelectedRaceId] = useState<SeekerAvatarType | null>(null);
  const [selectedClassId, setSelectedClassId] = useState<SeekerClass | null>(null);
  const [selectedGender, setSelectedGender] = useState<SeekerGender | null>(null);
  const [selectedAlignment, setSelectedAlignment] = useState<SeekerEnergyAlignment | null>(null);
  const [selectedAura, setSelectedAura] = useState<SeekerAuraColor | null>(null);
  const [selectedVisualFilter, setSelectedVisualFilter] = useState<SeekerVisualFilter | null>(null);
  const [selectedSelfTraits, setSelectedSelfTraits] = useState<string[]>([]);
  const [selectedCodexTraits, setSelectedCodexTraits] = useState<string[]>([]);
  const [generatedProfile, setGeneratedProfile] = useState<SeekerProfile | null>(null);
  const [isWeaving, setIsWeaving] = useState(false);

  const { generateImage, isGenerating: isGeminiBusy } = useGemini();

  const selectedRace = useMemo(() => 
    AVATAR_RACES.find(r => r.id === selectedRaceId), 
  [selectedRaceId]);

  const selectedClass = useMemo(() =>
    SEEKER_CLASSES.find(c => c.id === selectedClassId),
  [selectedClassId]);

  const selectedAuraOption = useMemo(() =>
    SEEKER_AURA_OPTIONS.find(a => a.id === selectedAura),
  [selectedAura]);

  const selectedFilterOption = useMemo(() => 
    SEEKER_VISUAL_FILTERS.find(f => f.id === selectedVisualFilter),
  [selectedVisualFilter]);

  const handleTraitToggle = (trait: string, type: 'self' | 'codex') => {
    if (type === 'self') {
      if (selectedSelfTraits.includes(trait)) {
        setSelectedSelfTraits(prev => prev.filter(t => t !== trait));
      } else if (selectedSelfTraits.length < 3) {
        setSelectedSelfTraits(prev => [...prev, trait]);
      }
    } else {
      if (selectedCodexTraits.includes(trait)) {
        setSelectedCodexTraits(prev => prev.filter(t => t !== trait));
      } else if (selectedCodexTraits.length < 2) {
        setSelectedCodexTraits(prev => [...prev, trait]);
      }
    }
  };

  const handleWeaveIdentity = useCallback(async () => {
    if (!seekerName || !selectedRace || !selectedClass || !selectedGender || !selectedAlignment || !selectedAura || !selectedVisualFilter || isWeaving || isGeminiBusy) return;

    setIsWeaving(true);
    addEchoMessage(AgentName.SeekerProfileWeaverAgent, `Initializing Weave Protocol for ${seekerName}...`, AGENT_PROFILES[AgentName.SeekerProfileWeaverAgent]?.colorClass);

    const filterPromptMod = selectedFilterOption?.promptMod || "";

    const prompt = `A high-quality, cinematic sci-fi fantasy portrait of a ${selectedGender} ${selectedRace.name} character named ${seekerName}, belonging to the ${selectedClass.name} archetype.
    Class Aesthetic: ${selectedClass.prompt}
    Race Characteristics: ${selectedRace.prompt}
    Faction/Alignment Visuals: ${selectedAlignment} (visualize as surrounding aura, lighting tone, or background atmosphere - e.g., Coven=purple runes, Zero=void static, Relic=tech glow).
    Aura Color: Radiating a strong ${selectedAura} glow or magical energy signature.
    Personality Traits visible in expression: ${selectedSelfTraits.join(", ")}.
    Metaphysical Aura Traits: ${selectedCodexTraits.join(", ")}.
    Visual Style Filter: ${filterPromptMod}
    Art Style: Tri-Sophian Codex aesthetic, mystical, intricate details, glowing runes, dark slate and neon accents, ethereal lighting, 8k resolution, masterpiece.
    The character is facing forward, framed like an ID card or tarot card.`;

    try {
      const imageUrl = await generateImage(prompt, 'gemini-2.5-flash-image');

      if (imageUrl) {
        const newProfile: SeekerProfile = {
          name: seekerName,
          race: selectedRace.id,
          class: selectedClass.id,
          gender: selectedGender,
          energyAlignment: selectedAlignment,
          auraColor: selectedAura,
          visualFilter: selectedVisualFilter,
          selfTraits: selectedSelfTraits,
          codexTraits: selectedCodexTraits,
          avatarImageUrl: imageUrl,
          generatedAt: Date.now()
        };
        setGeneratedProfile(newProfile);
        setStep(4); // Move to Result Step

        if (onProfileCreated) {
            onProfileCreated(newProfile);
        }

        addEchoMessage(
            AgentName.SeekerProfileWeaverAgent, 
            `Identity Weave Complete. Welcome, ${seekerName} of the ${selectedRace.name}. Profile added to Reliquary.`, 
            'text-emerald-400',
            false,
            { eventType: HistoricalEventType.SEEKER_PROFILE_GENERATED, eventData: { profileName: seekerName, race: selectedRace.id, class: selectedClass.id, gender: selectedGender, energyAlignment: selectedAlignment, aura: selectedAura, traits: [...selectedSelfTraits, ...selectedCodexTraits] } }
        );
      } else {
        addEchoMessage(AgentName.SeekerProfileWeaverAgent, "Weave failed. The image could not be formed.", 'text-rose-400');
      }
    } catch (error) {
      console.error("Profile Weaving Error:", error);
      addEchoMessage(AgentName.SeekerProfileWeaverAgent, "Critical Error in Weave Protocol.", 'text-rose-400');
    } finally {
      setIsWeaving(false);
    }
  }, [seekerName, selectedRace, selectedClass, selectedGender, selectedAlignment, selectedAura, selectedVisualFilter, selectedSelfTraits, selectedCodexTraits, isWeaving, isGeminiBusy, generateImage, addEchoMessage, onProfileCreated, selectedFilterOption]);

  const resetForm = () => {
    setStep(1);
