```tsx
import React, { useState, useCallback, useMemo, useEffect } from 'react';
import type { SeekerProfileWeaverPanelProps, SeekerProfile, MarketItem } from '../../types';
import { AgentName, SeekerAvatarType, HistoricalEventType, SeekerGender, SeekerEnergyAlignment, SeekerClass, SeekerAuraColor, SeekerVisualFilter, ArtifactRarity, MarketItemType } from '../../types';
import { AGENT_PROFILES, AVATAR_RACES, TRAIT_LISTS, ALL_GENDERS_LIST, ALL_ALIGNMENTS_LIST, SEEKER_CLASSES, SEEKER_AURA_OPTIONS, SEEKER_VISUAL_FILTERS, MARKET_ITEMS, EVOLUTION_THRESHOLDS } from '../../constants';
import { useGemini } from '../../context/GeminiIntegrationContext';
import { Button } from '../ui/Button';

const SeekerProfileWeaverPanel: React.FC<SeekerProfileWeaverPanelProps> = ({ addEchoMessage, onProfileCreated, onUpdateProfile, existingProfile, width, height }) => {
  const [mode, setMode] = useState<'create' | 'dashboard' | 'market' | 'lineage'>('create');

  // Creation Flow State
  const [step, setStep] = useState<number>(1);
  const [seekerName, setSeekerName] = useState("");
  const [selectedRaceId, setSelectedRaceId] = useState<SeekerAvatarType | null>(null);
  const [selectedClassId, setSelectedClassId] = useState<SeekerClass | null>(null);
  const [selectedGender, setSelectedGender] = useState<SeekerGender | null>(null);
  const [selectedAlignment, setSelectedAlignment] = useState<SeekerEnergyAlignment | null>(null);
  const [selectedAura, setSelectedAura] = useState<SeekerAuraColor | null>(null);
  const [selectedVisualFilter, setSelectedVisualFilter] = useState<SeekerVisualFilter | null>(null);
  const [selectedSelfTraits, setSelectedSelfTraits] = useState<string[]>([]);
  const [selectedCodexTraits, setSelectedCodexTraits] = useState<string[]>([]);
  const [isWeaving, setIsWeaving] = useState(false);

  // Dashboard/Active State
  const [activeProfile, setActiveProfile] = useState<SeekerProfile | null>(existingProfile || null);

  // Market Filter State
  const [marketFilter, setMarketFilter] = useState<MarketItemType | 'All'>('All');

  const { generateImage, isGenerating: isGeminiBusy } = useGemini();

  useEffect(() => {
    if (existingProfile) {
      setActiveProfile(existingProfile);
      setMode('dashboard');
    }
  }, [existingProfile]);

  // GDP Calculation Helper
  const calculateGDP = (profile: SeekerProfile) => {
    const fluxValue = profile.flux;
    const inventoryValue = profile.inventory.reduce((sum, item) => sum + item.cost, 0);
    const experienceValue = profile.experience * 0.5; // Weight XP
    const levelBonus = profile.level * 2000;
    return Math.floor(fluxValue + inventoryValue + experienceValue + levelBonus);
  };

  // Create a deep copy snapshot for lineage
  const createLineageSnapshot = (profile: SeekerProfile): SeekerProfile => {
      // Remove lineage from the snapshot to prevent infinite recursion/bloat
      const { lineage, ...snapshotData } = profile; 
      // Re-add empty lineage or just omit it. Casting to SeekerProfile.
      return { ...snapshotData, lineage: [] } as SeekerProfile; 
  };


  const selectedRace = useMemo(() => AVATAR_RACES.find(r => r.id === selectedRaceId), [selectedRaceId]);
  const selectedClass = useMemo(() => SEEKER_CLASSES.find(c => c.id === selectedClassId), [selectedClassId]);

  const handleTraitToggle = (trait: string, type: 'self' | 'codex') => {
    if (type === 'self') {
      if (selectedSelfTraits.includes(trait)) setSelectedSelfTraits(prev => prev.filter(t => t !== trait));
      else if (selectedSelfTraits.length < 3) setSelectedSelfTraits(prev => [...prev, trait]);
    } else {
      if (selectedCodexTraits.includes(trait)) setSelectedCodexTraits(prev => prev.filter(t => t !== trait));
      else if (selectedCodexTraits.length < 2) setSelectedCodexTraits(prev => [...prev, trait]);
    }
  };

  // --- ADVANCED PROMPT ENGINE ---
  const constructEpicPrompt = (profileData: Partial<SeekerProfile>, context: string) => {
    const race = AVATAR_RACES.find(r => r.id === profileData.race);
    const cls = SEEKER_CLASSES.find(c => c.id === profileData.class);
    const filter = SEEKER_VISUAL_FILTERS.find(f => f.id === profileData.visualFilter);
    const weapon = profileData.equippedWeapon;
    const companion = profileData.equippedCompanion;
    const env = profileData.equippedBackground;
    const aura = profileData.auraColor;
    const level = profileData.level || 1;

    // Level-based descriptors
    let powerDescriptor = "Novice, aspiring, grounded";
    let gearQuality = "Basic, functional gear";
    if (level >= 3) {
        powerDescriptor = "Veteran, battle-hardened, glowing with inner power";
        gearQuality = "Ornate, rune-etched armor and gear";
    }
    if (level >= 5) {
        powerDescriptor = "Transcendent, demigod-like presence, reality-warping energy";
        gearQuality = "Legendary, mythic regalia, floating components";
    }

    // Dynamic Elements
    let dynamicElements = "";
    if (weapon) {
        dynamicElements += `\n- CENTRAL ACTION: Wielding a ${weapon.name} (${weapon.visualPromptMod}).`;
    } else {
        dynamicElements += `\n- ACTION: Casting a spell or interacting with a holographic interface.`;
    }

    if (companion) {
        dynamicElements += `\n- COMPANION: ${companion.visualPromptMod}.`;
    }

    if (env) {
        dynamicElements += `\n- SETTING/BACKGROUND: ${env.visualPromptMod}.`;
    } else {
        dynamicElements += `\n- SETTING: Abstract void or high-tech temple background.`;
    }

    // Final Prompt Assembly
    return `
    Create a Masterpiece Character Portrait. 8k Resolution, Cinematic Lighting, Raytraced.

    SUBJECT IDENTITY:
    - Name: ${profileData.name}
    - Race: ${race?.name} (${race?.prompt})
    - Class: ${cls?.name} (${cls?.prompt})
    - Gender: ${profileData.gender}
    - Power Level: ${powerDescriptor}

    VISUALS & GEAR:
    - Gear Quality: ${gearQuality}
    - Aura: Intense ${aura} bioluminescence/energy field.
    - Faction Aesthetic: ${profileData.energyAlignment} style elements.
    ${dynamicElements}

    STYLE & ATMOSPHERE:
    - Art Style: ${filter?.promptMod || "Sci-fi Fantasy, Hyper-detailed, Digital Paint"}.
    - Composition: Epic character shot, centered, depth of field background.
    - Context: ${context}.
    `;
  };

  const generateProfileImage = async (profileData: Partial<SeekerProfile>, intention: string) => {
    const prompt = constructEpicPrompt(profileData, intention);
    return await generateImage(prompt, 'gemini-2.5-flash-image');
  };

  const handleWeaveIdentity = async () => {
    if (!seekerName || !selectedRaceId || !selectedClassId || !selectedGender || !selectedAlignment || !selectedAura || !selectedVisualFilter) return;

    setIsWeaving(true);
    addEchoMessage(AgentName.SeekerProfileWeaverAgent, `Initializing Weave Protocol for ${seekerName}...`, 'text-fuchsia-300');

    try {
        const tempProfile: Partial<SeekerProfile> = {
            name: seekerName,
            race: selectedRaceId,
            class: selectedClassId,
            gender: selectedGender,
            energyAlignment: selectedAlignment,
            auraColor: selectedAura,
            visualFilter: selectedVisualFilter,
            selfTraits: selectedSelfTraits,
            codexTraits: selectedCodexTraits,
            level: 1,
        };

        const imageUrl = await generateProfileImage(tempProfile, "Genesis");

        if (imageUrl) {
            const newProfile: SeekerProfile = {
                ...tempProfile as SeekerProfile,
                avatarImageUrl: imageUrl,
                generatedAt: Date.now(),
                experience: 0,
                flux: 500, // Starting currency
                inventory: [],
                lineage: [], // Init empty lineage
                gdp: 500, // Initial GDP
            };
            setActiveProfile(newProfile);
            setMode('dashboard');
            if (onProfileCreated) onProfileCreated(newProfile);

            addEchoMessage(AgentName.SeekerProfileWeaverAgent, `Identity Weave Complete. Welcome, ${seekerName}. Profile active.`, 'text-emerald-400');
        } else {
            addEchoMessage(AgentName.SeekerProfileWeaverAgent, "Weave failed. The image could not be formed.", 'text-rose-400');
        }
    } catch (error) {
      console.error("Profile Weaving Error:", error);
      addEchoMessage(AgentName.SeekerProfileWeaverAgent, "Critical Error in Weave Protocol.", 'text-rose-400');
    } finally {
      setIsWeaving(false);
    }
  };

  const handleBuyItem = (item: MarketItem) => {
    if (!activeProfile) return;
    if (activeProfile.inventory.some(i => i.id === item.id) && item.type !== 'Consumable') {
        addEchoMessage(AgentName.ChronicleReliquaryAgent, `You already possess the ${item.name}.`, 'text-yellow-400');
        return;
    }

    if (activeProfile.flux >= item.cost) {
        const updatedProfile = {
            ...activeProfile,
            flux: activeProfile.flux - item.cost,
            inventory: [...activeProfile.inventory, item]
        };
        updatedProfile.gdp = calculateGDP(updatedProfile); // Recalc GDP
        setActiveProfile(updatedProfile);
        if (onUpdateProfile) onUpdateProfile(updatedProfile);
        addEchoMessage(AgentName.ChronicleReliquaryAgent, `Acquired ${item.name}. Added to Inventory.`, 'text-amber-300');
    } else {
        addEchoMessage(AgentName.System, `Insufficient Flux. Need ${item.cost - activeProfile.flux} more.`, 'text-rose-400');
    }
  };

  const handleEquipItem = (item: MarketItem) => {
      if (!activeProfile) return;
      let updatedProfile = { ...activeProfile };

      if (item.type === 'Weapon') updatedProfile.equippedWeapon = item;
      if (item.type === 'Companion') updatedProfile.equippedCompanion = item;
      if (item.type === 'Environment') updatedProfile.equippedBackground = item;

      setActiveProfile(updatedProfile);
      if (onUpdateProfile) onUpdateProfile(updatedProfile);
      addEchoMessage(AgentName.SeekerProfileWeaverAgent, `Equipped ${item.name}. Re-forge visuals to integrate.`, 'text-cyan-300');
  };

  const handleSalvageItem = (item: MarketItem) => {
      if (!activeProfile) return;
      if (!confirm(`Salvage ${item.name} for ${Math.floor(item.cost * 0.5)} Flux? This cannot be undone.`)) return;

      const salvageValue = Math.floor(item.cost * 0.5);
      const updatedInventory = activeProfile.inventory.filter(i => i.id !== item.id);

      let equippedW = activeProfile.equippedWeapon;
      let equippedC = activeProfile.equippedCompanion;
      let equippedE = activeProfile.equippedBackground;

      if (equippedW?.id === item.id) equippedW = undefined;
      if (equippedC?.id === item.id) equippedC = undefined;
      if (equippedE?.id === item.id) equippedE = undefined;

      const updatedProfile = {
          ...activeProfile,
          flux: activeProfile.flux + salvageValue,
          inventory: updatedInventory,
          equippedWeapon: equippedW,
          equippedCompanion: equippedC,
          equippedBackground: equippedE
      };
      updatedProfile.gdp = calculateGDP(updatedProfile);
      setActiveProfile(updatedProfile);
      if (onUpdateProfile) onUpdateProfile(updatedProfile);
      addEchoMessage(AgentName.ChronicleReliquaryAgent, `Salvaged ${item.name}. Gained ${salvageValue} Flux.`, 'text-amber-400');
  };

  const handleReforgeVisuals = async () => {
      if (!activeProfile || isWeaving || isGeminiBusy) return;

      // Save lineage before reforge, preserving history
      const oldSnapshot = createLineageSnapshot(activeProfile);

      setIsWeaving(true);
      addEchoMessage(AgentName.SeekerProfileWeaverAgent, `Re-forging identity with Level ${activeProfile.level} resonance...`, 'text-fuchsia-300');
      try {
        const imageUrl = await generateProfileImage(activeProfile, "Evolutionary Reforge");
        if (imageUrl) {
            const updatedProfile = { 
                ...activeProfile, 
                avatarImageUrl: imageUrl,
                lineage: [...(activeProfile.lineage || []), oldSnapshot] // Push old state to lineage
            };
            setActiveProfile(updatedProfile);
            if (onUpdateProfile) onUpdateProfile(updatedProfile);
            addEchoMessage(AgentName.SeekerProfileWeaverAgent, "Visual manifestation updated. Previous incarnation archived in Lineage.", 'text-emerald-400');
        }
      } catch (e) {
        console.error(e);
        addEchoMessage(AgentName.SeekerProfileWeaverAgent, "Reforge failed.", 'text-rose-400');
      } finally {
        setIsWeaving(false);
      }
  };

  const handleLevelUp = () => {
    if (!activeProfile) return;
    const nextLevel = activeProfile.level + 1;
    const cost = activeProfile.level * 1000;

    if (activeProfile.flux >= cost) {
         // Snapshot current state for lineage before leveling up
         const oldSnapshot = createLineageSnapshot(activeProfile);

         const updatedProfile = {
            ...activeProfile,
            level: nextLevel,
            flux: activeProfile.flux - cost,
            experience: activeProfile.experience + 1000,
            lineage: [...(activeProfile.lineage || []), oldSnapshot] // Push to lineage
        };
        updatedProfile.gdp = calculateGDP(updatedProfile);

        setActiveProfile(updatedProfile);
        if (onUpdateProfile) onUpdateProfile(updatedProfile);
        addEchoMessage(AgentName.System, `Ascension Complete! You are now Level ${nextLevel}. Previous state archived.`, 'text-amber-300 animate-pulse');
    } else {
        addEchoMessage(AgentName.System, `Ascension denied. Requires ${cost} Flux.`, 'text-rose-400');
    }
  };

  const handleClaimFlux = () => {
      if (!activeProfile) return;
      const reward = 50;
      const updatedProfile = { ...activeProfile, flux: activeProfile.flux + reward };
      updatedProfile.gdp = calculateGDP(updatedProfile);
      setActiveProfile(updatedProfile);
      if (onUpdateProfile) onUpdateProfile(updatedProfile);
      addEchoMessage(AgentName.System, `Daily Resonance Collected: +${reward} Flux.`, 'text-emerald-300');
  }

  const handleVoidGamble = () => {
    if (!activeProfile) return;
    const wager = 100;
    if (activeProfile.flux < wager) {
        addEchoMessage(AgentName.System, `Insufficient Flux for the Void Gamble (Requires ${wager}).`, 'text-rose-400');
        return;
    }
    const win = Math.random() > 0.5;
    if (win) {
        const reward = wager * 2;
        const updatedProfile = { ...activeProfile, flux: activeProfile.flux + wager };
        updatedProfile.gdp = calculateGDP(updatedProfile);
        setActiveProfile(updatedProfile);
        if (onUpdateProfile) onUpdateProfile(updatedProfile);
        addEchoMessage(AgentName.CosmicEvent, `The Void Favors You! Won ${reward} Flux.`, 'text-emerald-300 font-bold');
    } else {
        const updatedProfile = { ...activeProfile, flux: activeProfile.flux - wager };
        updatedProfile.gdp = calculateGDP(updatedProfile);
        setActiveProfile(updatedProfile);
        if (onUpdateProfile) onUpdateProfile(updatedProfile);
        addEchoMessage(AgentName.EntropicHeart, `The Entropy claims your offering. Lost ${wager} Flux.`, 'text-rose-500 italic');
    }
  };

  // --- VIEW: CREATION FUNNEL ---
  if (mode === 'create') {
    return (
        <div className="seeker-profile-weaver-panel bg-slate-900/90 backdrop-blur-xl border border-amber-500/50 rounded-xl shadow-2xl p-6 text-slate-100 flex flex-col my-4 relative z-10" style={{ width: width ? `${width}px` : '100%', height: height ? `${height}px` : 'auto', minHeight: '600px' }}>
          <h3 className="text-2xl font-cinzel font-bold text-amber-300 mb-2 text-center tracking-wider drop-shadow-[0_1px_2px_rgba(245,158,11,0.6)]">
            <i className="ri-id-card-line mr-3"></i>Seeker Profile Weaver
          </h3>

          <div className="flex justify-center mb-6">
            <div className="flex gap-2">
                {[1,2,3,4].map(s => (
                    <div key={s} className={`h-1.5 w-8 rounded-full ${step >= s ? 'bg-amber-500' : 'bg-slate-700'}`}></div>
                ))}
            </div>
          </div>

          <div className="flex-grow flex flex-col gap-4 overflow-y-auto custom-scrollbar pr-2">
            {step === 1 && (
                <div className="space-y-4 animate-fade-in-up">
                    <h4 className="text-lg font-cinzel text-amber-200 text-center">Step 1: Core Essence</h4>
                    <div className="space-y-2">
                        <label className="block text-sm font-cinzel text-slate-300">Seeker Designation</label>
                        <input type="text" value={seekerName} onChange={(e) => setSeekerName(e.target.value)} className="w-full bg-slate-800/50 border border-slate-600 rounded p-2 text-slate-100 focus:ring-2 focus:ring-amber-500 outline-none font-mono" placeholder="Enter your name..." />
                    </div>
                    <div className="space-y-2">
                        <label className="block text-sm font-cinzel text-slate-300">Identity Resonance</label>
                        <div className="flex flex-wrap gap-2">{ALL_GENDERS_LIST.map(g => <button key={g} onClick={() => setSelectedGender(g)} className={`px-3 py-1.5 text-xs rounded border ${selectedGender === g ? 'bg-amber-700/60 border-amber-500 text-white' : 'bg-slate-800/40 border-slate-700 text-slate-400'}`}>{g}</button>)}</div>
                    </div>
                    <div className="space-y-2">
                         <label className="block text-sm font-cinzel text-slate-300">Faction Alignment</label>
                         <div className="grid grid-cols-2 gap-2">{ALL_ALIGNMENTS_LIST.map(a => <button key={a} onClick={() => setSelectedAlignment(a)} className={`px-2 py-1.5 text-[10px] rounded border ${selectedAlignment === a ? 'bg-indigo-900/60 border-indigo-500 text-white' : 'bg-slate-800/40 border-slate-700 text-slate-400'}`}>{a}</button>)}</div>
                    </div>
                     <div className="mt-4"><Button onClick={() => setStep(2)} disabled={!seekerName || !selectedGender || !selectedAlignment} className="w-full bg-amber-600 hover:bg-amber-500">Next: Form <i className="ri-arrow-right-line ml-1"></i></Button></div>
                </div>
            )}
            {step === 2 && (
                 <div className="space-y-4 animate-fade-in-up">
                    <h4 className="text-lg font-cinzel text-amber-200 text-center">Step 2: Manifest Form</h4>
                    <div className="space-y-2">
                        <label className="block text-sm font-cinzel text-slate-300">Avatar Morphology</label>
                        <div className="grid grid-cols-2 gap-2 max-h-40 overflow-y-auto custom-scrollbar">{AVATAR_RACES.map(r => <button key={r.id} onClick={() => setSelectedRaceId(r.id)} className={`p-2 rounded border text-left text-xs ${selectedRaceId === r.id ? 'bg-emerald-900/40 border-emerald-500 text-white' : 'bg-slate-800/40 border-slate-700 text-slate-400'}`}>{r.name}</button>)}</div>
                    </div>
                     <div className="space-y-2">
                        <label className="block text-sm font-cinzel text-slate-300">Archetype Class</label>
                        <div className="grid grid-cols-2 gap-2 max-h-40 overflow-y-auto custom-scrollbar">{SEEKER_CLASSES.map(c => <button key={c.id} onClick={() => setSelectedClassId(c.id)} className={`p-2 rounded border text-left text-xs ${selectedClassId === c.id ? 'bg-purple-900/40 border-purple-500 text-white' : 'bg-slate-800/40 border-slate-700 text-slate-400'}`}>{c.name}</button>)}</div>
                    </div>
                     <div className="mt-4 flex gap-2"><Button onClick={() => setStep(1)} className="bg-slate-700">Back</Button><Button onClick={() => setStep(3)} disabled={!selectedRaceId || !selectedClassId} className="flex-grow bg-amber-600 hover:bg-amber-500">Next: Resonance <i className="ri-arrow-right-line ml-1"></i></Button></div>
                 </div>
            )}
             {step === 3 && (
                 <div className="space-y-4 animate-fade-in-up">
                    <h4 className="text-lg font-cinzel text-amber-200 text-center">Step 3: Aetheric Resonance</h4>
                    <div className="space-y-2">
                         <label className="block text-sm font-cinzel text-slate-300">Aura Color</label>
                         <div className="grid grid-cols-4 gap-2">{SEEKER_AURA_OPTIONS.map(a => <button key={a.id} onClick={() => setSelectedAura(a.id)} className={`h-8 rounded border ${selectedAura === a.id ? 'ring-2 ring-white' : 'border-slate-700'}`} style={{backgroundColor: a.hex}} title={a.name}></button>)}</div>
                    </div>
                    <div className="space-y-2">
                         <label className="block text-sm font-cinzel text-slate-300">Visual Filter</label>
                         <div className="grid grid-cols-3 gap-2">{SEEKER_VISUAL_FILTERS.map(f => <button key={f.id} onClick={() => setSelectedVisualFilter(f.id)} className={`p-1.5 text-[10px] rounded border ${selectedVisualFilter === f.id ? 'bg-pink-900/40 border-pink-500 text-white' : 'bg-slate-800/40 border-slate-700 text-slate-400'}`}>{f.name}</button>)}</div>
                    </div>
                    <div className="space-y-2">
