                    <div className="mt-4 flex gap-2"><Button onClick={() => setStep(2)} className="bg-slate-700">Back</Button><Button onClick={() => setStep(4)} disabled={!selectedAura || !selectedVisualFilter} className="flex-grow bg-amber-600 hover:bg-amber-500">Next: Finalize <i className="ri-arrow-right-line ml-1"></i></Button></div>
