  }

  // --- VIEW: DASHBOARD (Active Profile) ---
  if (!activeProfile) return null;
  const race = AVATAR_RACES.find(r => r.id === activeProfile.race);

  return (
    <div className="seeker-dashboard-panel bg-slate-950/95 backdrop-blur-xl border border-slate-700 rounded-xl shadow-2xl flex flex-col my-4 relative z-10 overflow-hidden" style={{ width: width ? `${width}px` : '100%', height: height ? `${height}px` : 'auto', minHeight: '600px' }}>

      {/* Top Bar */}
      <div className="bg-slate-900 border-b border-slate-700 p-4 flex justify-between items-center">
