import MutationLoomPanel from './components/panels/MutationLoomPanel';
import SigilBloomVariantPanel from './components/panels/SigilBloomVariantPanel';
import AgentInspectorPanel from './components/panels/AgentInspectorPanel';
import GlyphVisualizationPanel from './components/panels/GlyphVisualizationPanel';
import HarmonicCorePanel from './components/panels/HarmonicCorePanel';
import EntropyDiagnosticsPanel from './components/panels/EntropyDiagnosticsPanel';
import CodexPandiumPanel from './components/panels/CodexPandiumPanel';
import MythicQuestPanel from './components/panels/MythicQuestPanel';

import type {
  EchoMessage, ResonanceEffect, PlacedGlyph, CanvasConnection,
  CodexArtifact, SeekerProfile, GlyphMutationNode, MutationLoomState, SigilVariant
} from './types';
import { AgentName, GeoMode, CodexModeId, ArtifactType, ArtifactRarity, VisualizationMatrixMode, BloodInkSpeciesName } from './types'; 
import {
  ALL_CANONICAL_AXIOMS, 
  INITIAL_RESONANCE_EFFECTS, INITIAL_ECHOES,
  AXIOM_RITUAL_ELEMENTS, BLOOD_INK_SPECIES_DATA
} from './constants';
import {
  generateInitialGrid, generateInitialAgents
} from './lib/simulationUtils'; 
import { SoundEngine } from './lib/SoundEngine';
import { getCodexModeDefinition } from './components/core/CodexModes';
import { useDreambloomSystem } from './hooks/useDreambloomSystem';

export const App: React.FC = () => {
  const [echoes, setEchoes] = useState<EchoMessage[]>(INITIAL_ECHOES);
  const [artifacts, setArtifacts] = useState<CodexArtifact[]>([]);
  const [systemEntropy, setSystemEntropy] = useState<number>(0.1); 
  const [masterEntropyOverride, setMasterEntropyOverride] = useState<number>(0); 
  const [isBootSequenceActive, setIsBootSequenceActive] = useState(true);

  // Mobile Responsiveness State
  const [screenWidth, setScreenWidth] = useState(typeof window !== 'undefined' ? window.innerWidth : 1200);
  const [screenHeight, setScreenHeight] = useState(typeof window !== 'undefined' ? window.innerHeight : 800);
  const [mobileTab, setMobileTab] = useState<'oracle' | 'weave' | 'system'>('weave');
  const isMobile = screenWidth < 768;

  // Module & Modal State
  const [activeModuleId, setActiveModuleId] = useState<string | null>(null);
  const [isOracleModalOpen, setIsOracleModalOpen] = useState(false); 
  const [isBugaModeActive, setIsBugaModeActive] = useState(false);
  const [agents, setAgents] = useState(generateInitialAgents());

  // Profile State
  const [activeProfile, setActiveProfile] = useState<SeekerProfile | null>(null);

  // --- STATE FOR PANELS ---
  const [glyphMutationNodes, setGlyphMutationNodes] = useState<GlyphMutationNode[]>([
      { id: 'mut-1', label: 'Alpha-Seed', glyphId: 'G-001', traits: ['Resonant', 'Ancient'], entropyLevel: 0.2, hasSyntaxThorns: false, agentInfluences: ['Gemini'], timestamp: Date.now() },
      { id: 'mut-2', label: 'Beta-Void', glyphId: 'G-002', traits: ['Hollow', 'Echoing'], entropyLevel: 0.5, hasSyntaxThorns: true, agentInfluences: ['Nevik'], timestamp: Date.now() },
      { id: 'mut-3', label: 'Gamma-Flame', glyphId: 'G-003', traits: ['Burning', 'Bright'], entropyLevel: 0.8, hasSyntaxThorns: false, agentInfluences: ['DeepSeek'], timestamp: Date.now() },
      { id: 'mut-4', label: 'Delta-Weave', glyphId: 'G-004', traits: ['Connected', 'Complex'], entropyLevel: 0.3, hasSyntaxThorns: false, agentInfluences: ['System'], timestamp: Date.now() },
  ]);
  const [mutationLoomState, setMutationLoomState] = useState<MutationLoomState>({
    glyph1Id: null, glyph2Id: null, isWeaving: false, entropyInjection: 0.5, traitFocus: []
  });
  const [sigilBloomVariants, setSigilBloomVariants] = useState<SigilVariant[]>([]);
  const [selectedBloomVariantId, setSelectedBloomVariantId] = useState<string | null>(null);
  const [isGeneratingBloomVariants, setIsGeneratingBloomVariants] = useState(false);
  const [selectedAgentForInspection, setSelectedAgentForInspection] = useState<any | null>(null);

  const soundEngineRef = useRef(new SoundEngine());

  const { invokeGemini, isGenerating: isGeminiGenerating } = useGemini();
  const [isMuted, setIsMuted] = useState(false);

  useEffect(() => {
    const handleResize = () => {
        setScreenWidth(window.innerWidth);
        setScreenHeight(window.innerHeight);
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // Force Weave Tab on load if no profile
  useEffect(() => {
      if (!isBootSequenceActive && !activeProfile && isMobile) {
          setMobileTab('weave');
      }
  }, [isBootSequenceActive, activeProfile, isMobile]);


  const addEchoMessage = useCallback((source: string, text: string, colorClass: string = 'text-slate-100', isAutoEcho: boolean = false, meta?: any) => {
    const newEcho: EchoMessage = {
      id: `echo-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      source,
      text,
      colorClass,
      isAutoEcho,
      meta,
      timestamp: new Date().toISOString()
    };
    setEchoes(prev => [newEcho, ...prev].slice(0, 100));

    if (!isAutoEcho && source !== AgentName.System) {
       soundEngineRef.current.playSFX('click');
    }
  }, []);

  const dreambloomSystem = useDreambloomSystem(addEchoMessage);

  const addArtifact = useCallback((artifact: CodexArtifact) => {
    setArtifacts(prev => [artifact, ...prev]);
    addEchoMessage(AgentName.ChronicleReliquaryAgent, `Artifact Acquired: ${artifact.name}`, 'text-amber-300');
    soundEngineRef.current.playSFX('success');
  }, [addEchoMessage]);

  const handleProfileCreated = useCallback((profile: SeekerProfile) => {
    setActiveProfile(profile);
    const newArtifact: CodexArtifact = {
        id: `artifact-id-${Date.now()}`,
        name: `${profile.name}'s Identity Card`,
        type: ArtifactType.SeekerID,
        rarity: ArtifactRarity.Rare,
        description: `Official Seeker Identity for ${profile.name} of the ${profile.race}. Alignment: ${profile.energyAlignment}.`,
        imageUrl: profile.avatarImageUrl || undefined,
        timestamp: Date.now(),
        energySignature: profile.energyAlignment,
        metaData: { 
            race: profile.race, 
            traits: profile.selfTraits.join(', ') 
        }
    };
    addArtifact(newArtifact);
  }, [addArtifact]);

  const handleUpdateProfile = useCallback((profile: SeekerProfile) => {
      setActiveProfile(profile);
  }, []);

  const [placedGlyphs, setPlacedGlyphs] = useState<PlacedGlyph[]>([]);
  const [connections, setConnections] = useState<CanvasConnection[]>([]);
  const [activeEffects, setActiveEffects] = useState<ResonanceEffect[]>(INITIAL_RESONANCE_EFFECTS);
  const [codexModeId, setCodexModeId] = useState<CodexModeId>(CodexModeId.ORIGIN_STATE);
  const [currentGeoMode, setCurrentGeoMode] = useState<GeoMode>(GeoMode.GlyphDNA);

  useEffect(() => {
    soundEngineRef.current.initializeDrone();
  }, []);

  useEffect(() => {
    soundEngineRef.current.toggleMute(isMuted);
  }, [isMuted]);

  const effectiveSystemEntropy = useMemo(() => {
    return Math.max(0, Math.min(1, systemEntropy + (masterEntropyOverride / 100)));
  }, [systemEntropy, masterEntropyOverride]);

  useEffect(() => {
    soundEngineRef.current.updateDrone(effectiveSystemEntropy);
  }, [effectiveSystemEntropy]);

  const handleToggleMute = () => setIsMuted(prev => !prev);
  const handleToggleBugaMode = () => setIsBugaModeActive(prev => {
    const newVal = !prev;
    addEchoMessage(AgentName.SystemControl, `Buga Bio-Resonance Mode ${newVal ? 'ACTIVATED' : 'DEACTIVATED'}.`, 'text-lime-400');
    return newVal;
  });

  const handleInvokeGeminiOracle = () => {
    setIsOracleModalOpen(true);
    addEchoMessage(AgentName.System, "Opening Oracle Sanctum...", "text-fuchsia-300");
  };

  const dummyHandler = () => {}; 
  const handleApplyOmegaAnchor = () => setSystemEntropy(Math.max(0, systemEntropy - 0.1));
  const handleSystemRestore = () => {
    if (confirm('This will reset the current session. Proceed?')) {
        window.location.reload();
    }
  };

  const currentModeDef = getCodexModeDefinition(codexModeId);
  const isOmegaAnchorDisabled = effectiveSystemEntropy <= 0.6 || currentModeDef?.entropySettings?.capEffectiveEntropyAt === 0.025;

  const handleWeaveGlyphs = async (g1: string, g2: string, entropy: number, traits: string[]) => {
      setMutationLoomState(prev => ({ ...prev, isWeaving: true }));
      await new Promise(resolve => setTimeout(resolve, 2000));
      const newNode: GlyphMutationNode = {
          id: `woven-${Date.now()}`,
          label: `Hybrid-${g1.slice(-3)}-${g2.slice(-3)}`,
          glyphId: `H-${Date.now()}`,
          traits: [...traits, 'Synthesized'],
          entropyLevel: (entropy + 0.5) / 2,
          hasSyntaxThorns: Math.random() > 0.7,
          agentInfluences: ['Weaver'],
          timestamp: Date.now(),
          parentId: [g1, g2]
      };
      setGlyphMutationNodes(prev => [...prev, newNode]);
      addEchoMessage(AgentName.RitualLoom, `Weaving successful. Created ${newNode.label}.`, 'text-teal-300');
      setMutationLoomState(prev => ({ ...prev, isWeaving: false, glyph1Id: null, glyph2Id: null }));
      return newNode;
  };

  const handleRevealBloomVariants = async (glyph: GlyphMutationNode) => {
      setIsGeneratingBloomVariants(true);
      await new Promise(resolve => setTimeout(resolve, 1500));
      setSigilBloomVariants([
          { id: 'v1', name: 'Nebula Bloom', description: 'Glows with starlight.', styleKeywords: ['Cosmic', 'Glowing'] },
          { id: 'v2', name: 'Void Thorn', description: 'Sharp, dark edges.', styleKeywords: ['Dark', 'Sharp'] },
          { id: 'v3', name: 'Crystal Echo', description: 'Fractal refractions.', styleKeywords: ['Crystalline', 'Prismatic'] }
      ]);
      setIsGeneratingBloomVariants(false);
  };


  // Responsive Dimensions for Modal Content
  const modalContentWidth = isMobile ? screenWidth - 24 : 1000;
  const modalContentHeight = isMobile ? screenHeight * 0.85 : 700;

  // Module Renderer
  const renderActiveModule = () => {
    switch (activeModuleId) {
        case 'mythic_quest':
             return <MythicQuestPanel 
                 width={modalContentWidth} 
                 height={modalContentHeight} 
                 activeProfile={activeProfile}
                 addEchoMessage={addEchoMessage}
                 onUpdateProfile={handleUpdateProfile}
                 onArtifactCreated={addArtifact}
             />;
        case 'codex_pandium':
            return <CodexPandiumPanel width={modalContentWidth} height={modalContentHeight} />;
        case 'emerald_tablet':
            return <EmeraldTabletDecryptionPanel currentSystemEntropy={effectiveSystemEntropy} currentEleganceIndex={0.95} addEchoMessage={addEchoMessage} width={modalContentWidth} height={modalContentHeight} />;
        case 'datachega':
            return <DatachegaResthetPanel addEchoMessage={addEchoMessage} />;
        case 'glyph_composer':
            return <GlyphComposerPanel isBugaModeActive={isBugaModeActive} addEchoMessage={addEchoMessage} />;
        case 'celestial_anomaly':
            return <CelestialAnomalyWeaverPanel width={modalContentWidth} height={modalContentHeight} addEchoMessage={addEchoMessage} />;
        case 'crm_dashboard':
            return <CosmicResonanceDashboardPanel width={modalContentWidth} height={modalContentHeight} addEchoMessage={addEchoMessage} />;
        case 'temporal_ops':
            return <TemporalOperationsConsolePanel width={modalContentWidth} height={modalContentHeight} addEchoMessage={addEchoMessage} />;
        case 'drift_differential':
            return <DriftDifferentialOverlay currentEntropy={effectiveSystemEntropy} glyphDriftHistory={[]} glyphMutationNodes={[]} currentRitualContext="System Direct Access" isGeminiGenerating={isGeminiGenerating} addEchoMessage={addEchoMessage} logGeminiNarrativeDriftEvent={() => {}} />;
        case 'dreambloom':
            return <DreambloomGenesisPanel 
              interpretations={dreambloomSystem.interpretations}
              onConjurePulse={dreambloomSystem.conjurePulse}
              isAutoActive={dreambloomSystem.isAutoActive}
              onToggleAuto={dreambloomSystem.toggleAuto}
              isLoading={dreambloomSystem.isLoading}
              addEchoMessage={addEchoMessage} 
              width={modalContentWidth}
              height={modalContentHeight}
            />;
        case 'exotic_mechanisms':
            return <ExoticMechanismsPanel currentEntropy={effectiveSystemEntropy} width={modalContentWidth} height={modalContentHeight} addEchoMessage={addEchoMessage} />;
        case 'crystal_garden':
            return <CrystalFormationPanel width={modalContentWidth} height={modalContentHeight} currentEntropy={effectiveSystemEntropy} />;
        case 'celestial_entropy':
            return <CelestialEntropyCyclePanel width={modalContentWidth} height={modalContentHeight} currentEntropy={effectiveSystemEntropy} />;
        case 'geometry_explorer':
            return <FlowerOfLifeEntropyExplorer width={modalContentWidth} height={modalContentHeight} currentEntropy={effectiveSystemEntropy} currentDisplayMode={VisualizationMatrixMode.SacredLattice} onSetDisplayMode={() => {}} />;
        case 'dimension_diagram':
            return <EntropyDimensionDiagramPanel width={modalContentWidth} height={modalContentHeight} currentEntropy={effectiveSystemEntropy} isFractalModeEnabled={true} />;
        case 'harmonic_core':
             return <HarmonicCorePanel lambdaValue={1.0} status={effectiveSystemEntropy < 0.3 ? "Stabilized" : "Oscillating"} eleganceIndex={0.95} />;
        case 'entropy_diagnostics':
             return <EntropyDiagnosticsPanel baseEntropy={systemEntropy} effectiveEntropy={effectiveSystemEntropy} masterEntropyOverridePercent={masterEntropyOverride} entropyHistory={[systemEntropy]} playbackTime={0} isPlaying={true} />;
        case 'aethel_update':
             return <AethelWeftCodexUpdatePanel panelHeight={modalContentHeight} />;
        case 'chronicle_display':
             return <AethelWeftChronicleDisplay chronicle={{ name: "The Lost Cycle", firstVerse: "In the beginning was the Echo...", currentWeavingMode: "Recursive", activeThemes: [{id:'1', name:'Void', signature:'∅ Void', colorClass:'text-purple-400', narrativeFunction:'Erasure', visualDriftCue:'Darkening'}] }} />;
        case 'phoenix_tablet':
             return <TabletOfThePhoenixPanel panelHeight={isMobile ? 400 : 600} />;
        case 'shatterpoint_trace':
             return <ShatterpointTracePanel objective="Locate Origin of Fracture" triggerGlyph="AX-Ω.001" axiomaticLinks={["AX-I", "AX-V"]} traceParameters={{temporal_filter: "Active", entropy_signature: "High", search_depth: "Deep", paradox_safety: "Engaged"}} oracleCommentary="The fracture is self-sustaining." />;
        case 'flora_chamber':
             return <BloodInkFloraChamber activeSpeciesName={BloodInkSpeciesName.ThornedRose} allSpeciesData={BLOOD_INK_SPECIES_DATA} />;
        case 'glyph_vis':
             return <GlyphVisualizationPanel panelHeight={modalContentHeight} glyphData={{id:'G-001', title:'Alpha', description:'The beginning.', resonance:'Harmonic', traits:['Prime'], linkedAxioms:['AX-I'], ritualAffinity:'High'}} pulseDetails={{label:'Alpha Pulse', glyphId:'G-001', state:'Active', mode:'Resonant', signatureFrequency:'432Hz', shadowArchiveDepth:'0', decryptionTraits:['None']}} visualizationDetails={{initialPhase:{title:'Ignition', form:'Spark', visual:'Bright', animation:'Pulse'}, sonicProfile:{description:'Low hum'}, finalForm:{description:'Stable Star', sigilPulse:['Bright'], overlay:'None'}}} systemNote={{uses:['Creation'], concludingQuote:'As it begins.'}} />;
        case 'buga_codex':
             return <BugaGlyphCodexPanel width={modalContentWidth} height={modalContentHeight} />;
        case 'peptide_sim':
             return <PeptideSimulationPanel width={modalContentWidth} height={modalContentHeight} addEchoMessage={addEchoMessage} />;
        case 'mutation_loom':
             return <MutationLoomPanel glyphMutationNodes={glyphMutationNodes} onWeaveGlyphs={handleWeaveGlyphs} mutationLoomState={mutationLoomState} setMutationLoomState={setMutationLoomState} addEchoMessage={addEchoMessage} isGeminiGenerating={isGeminiGenerating} />;
        case 'sigil_bloom':
             return <SigilBloomVariantPanel glyphMutationNodes={glyphMutationNodes} onRevealBloomVariants={handleRevealBloomVariants} sigilBloomVariants={sigilBloomVariants} selectedBloomVariantId={selectedBloomVariantId} onSelectBloomVariant={setSelectedBloomVariantId} isGeneratingBloomVariants={isGeneratingBloomVariants} isGeminiBusy={isGeminiGenerating} />;
        case 'agent_directory':
             return (
                 <div className="agent-directory-wrapper bg-slate-900/80 p-6 rounded-xl border border-indigo-500/50" style={{ width: modalContentWidth, height: modalContentHeight }}>
                     <h3 className="text-xl font-cinzel text-indigo-300 mb-4 text-center">Agent Directory</h3>
                     <div className="grid grid-cols-2 md:grid-cols-3 gap-4 overflow-y-auto max-h-[90%] custom-scrollbar">
                         {agents.map(agent => (
                             <button key={agent.id} onClick={() => setSelectedAgentForInspection(agent)} className="p-3 bg-slate-800/60 border border-slate-700 hover:bg-slate-700 hover:border-indigo-500 rounded-lg text-left transition-all">
                                 <div className="font-bold text-slate-200">{agent.name}</div>
                                 <div className="text-xs text-slate-400">{agent.race} | {agent.faction}</div>
                             </button>
                         ))}
                     </div>
                     {selectedAgentForInspection && (
                         <div className="fixed inset-0 z-[2200] flex items-center justify-center bg-black/50 backdrop-blur-sm" onClick={() => setSelectedAgentForInspection(null)}>
                             <div className="relative" onClick={e => e.stopPropagation()}>
                                <AgentInspectorPanel agent={selectedAgentForInspection} onClose={() => setSelectedAgentForInspection(null)} />
                             </div>
                         </div>
                     )}
                 </div>
             );

        default:
            return null;
    }
  };

  const getModuleTitle = () => {
    const allModules = [
      { id: 'mythic_quest', label: 'Astral Odyssey' },
      { id: 'codex_pandium', label: 'Codex Pandium' },
      { id: 'emerald_tablet', label: 'Emerald Tablet' },
      { id: 'datachega', label: 'Datachega Resthet' },
      { id: 'glyph_composer', label: 'Glyph Composer' },
      { id: 'celestial_anomaly', label: 'Celestial Anomaly: 14 Herculis' },
      { id: 'crm_dashboard', label: 'Cosmic Resonance Dashboard' },
      { id: 'temporal_ops', label: 'Temporal Ops Console' },
      { id: 'drift_differential', label: 'Drift Differential Analysis' },
      { id: 'dreambloom', label: 'Dreambloom Genesis Matrix' },
      { id: 'exotic_mechanisms', label: 'Exotic Mechanisms' },
      { id: 'crystal_garden', label: 'Crystal Garden' },
      { id: 'celestial_entropy', label: 'Celestial Entropy Cycle' },
      { id: 'geometry_explorer', label: 'Geometry Explorer' },
      { id: 'dimension_diagram', label: 'Entropy-Dimension Diagram' },
      { id: 'harmonic_core', label: 'Harmonic Core Monitor' },
      { id: 'entropy_diagnostics', label: 'System Entropy Diagnostics' },
      { id: 'aethel_update', label: 'Aethel-Weft Updates' },
      { id: 'chronicle_display', label: 'Chronicle Resonance' },
      { id: 'phoenix_tablet', label: 'Tablet of the Phoenix' },
      { id: 'shatterpoint_trace', label: 'Shatterpoint Trace' },
      { id: 'flora_chamber', label: 'Blood-Ink Flora Chamber' },
      { id: 'glyph_vis', label: 'Deep Glyph Visualization' },
      { id: 'buga_codex', label: 'Buga Glyph Codex' },
      { id: 'peptide_sim', label: 'Peptide Simulator' },
      { id: 'mutation_loom', label: 'Mutation Loom' },
      { id: 'sigil_bloom', label: 'Sigil Bloom Variants' },
      { id: 'agent_directory', label: 'Agent Directory' },
    ];
    return allModules.find(m => m.id === activeModuleId)?.label || 'System Module';
  };

  return (
    <SystemStateProvider value={{ 
        entropy: effectiveSystemEntropy, 
        activeTraits: [], 
        playbackStatus: 'stopped', 
        activeGlyph: null,
        negentropyLevel: 1 - effectiveSystemEntropy, 
        isNegentropyStable: effectiveSystemEntropy < 0.3
    }}>
        {isBootSequenceActive ? (
            <BootSequence onComplete={() => setIsBootSequenceActive(false)} />
        ) : (
            <div className="flex flex-col h-screen bg-slate-900 text-white overflow-hidden relative font-cormorant">
                <VoidEtchingOverlay entropy={effectiveSystemEntropy} />
                <Header 
                    currentCodexModeId={codexModeId}
                    activateCodexMode={setCodexModeId}
                    masterEntropyOverride={masterEntropyOverride}
                    onSetMasterEntropyOverride={setMasterEntropyOverride}
                    isMuted={isMuted}
                    onToggleMute={handleToggleMute}
                    onProvokeThornedRose={dummyHandler}
                    onTuneFrequency={dummyHandler}
                    onRecallAncestor={dummyHandler}
                    onBurnPetals={dummyHandler}
                    onAwakenLotusDream={dummyHandler}
                    onPulseAstralJasmine={dummyHandler}
                    onGraftThorns={dummyHandler}
                    onToggleAutoEcho={dummyHandler}
                    onAmplifyVoices={dummyHandler}
                    onSeedDream={dummyHandler}
                    isAutoEchoPaused={false}
                    onInvokeGeminiOracle={handleInvokeGeminiOracle} 
                    onContextualOracleQuery={handleInvokeGeminiOracle} 
                    onToggleAshfall={dummyHandler}
                    showAshfall={false}
                    isMasterEntropyLocked={false}
                    showLogicWebDebug={false}
                    onToggleLogicWebDebug={dummyHandler}
                    isAuditing={false}
                    onToggleAuditMode={dummyHandler}
                    isAuditModeLocked={false}
                    onDumpThreadSummary={dummyHandler}
                    showSigilOverlay={false}
                    onToggleSigilOverlay={dummyHandler}
                    onTraceThreadcoil={dummyHandler}
                    onReEnterJunction={dummyHandler}
                    onExtractSigil={dummyHandler}
                    isBugaModeActive={isBugaModeActive}
                    onToggleBugaMode={handleToggleBugaMode}
                    // Mobile specific
                    onApplyOmegaAnchor={handleApplyOmegaAnchor}
                    onSystemRestore={handleSystemRestore}
                    isOmegaAnchorDisabled={isOmegaAnchorDisabled}
                />

                {/* Main Content Area */}
                <div className="flex-grow flex flex-col md:flex-row overflow-hidden relative z-10">

                    {/* Left Column (Oracle) */}
                    <div className={`${mobileTab === 'oracle' ? 'flex' : 'hidden'} md:flex w-full md:w-1/4 p-4 overflow-y-auto custom-scrollbar border-r border-slate-700/50 bg-slate-900/50 backdrop-blur-sm flex-col gap-4 pb-20 md:pb-4`}>
                        <CosmicEntropyGeometryGenerator 
                            currentEntropy={effectiveSystemEntropy}
                            currentPhase="Resonance"
                            chaliceStatus="Filling"
                            width={isMobile ? screenWidth - 32 : 350} 
                            height={350}
                            currentGeoMode={currentGeoMode}
                            onSetGeoMode={setCurrentGeoMode}
                        />
                        <EchoScribePanel echoes={echoes} />
                    </div>

                    {/* Center Column (Weave) */}
                    <div className={`${mobileTab === 'weave' ? 'flex' : 'hidden'} md:flex w-full md:w-1/2 p-4 overflow-y-auto custom-scrollbar flex-col gap-6 relative pb-20 md:pb-4`}>
                        <SeekerProfileWeaverPanel 
                            addEchoMessage={addEchoMessage}
                            onProfileCreated={handleProfileCreated}
                            onUpdateProfile={handleUpdateProfile}
                            existingProfile={activeProfile}
                            width={isMobile ? screenWidth - 32 : undefined}
                        />
                        {/* Add Launch Button for Mythic Quest if not active */}
                         <div className="text-center">
                            <button 
                                onClick={() => setActiveModuleId('mythic_quest')}
                                className="px-4 py-2 bg-gradient-to-r from-purple-700 to-indigo-700 rounded-lg text-white font-cinzel text-sm hover:from-purple-600 hover:to-indigo-600 border border-purple-500/50 shadow-lg"
                            >
                                <i className="ri-sword-line mr-2"></i>Launch Astral Odyssey
                            </button>
                        </div>

                        <RitualCanvasContainer 
                            addEchoMessage={addEchoMessage}
                            placedGlyphs={placedGlyphs}
                            setPlacedGlyphs={setPlacedGlyphs}
                            connections={connections}
                            setConnections={setConnections}
                            onRitualActivated={() => {}} 
                            availableAxiomElements={AXIOM_RITUAL_ELEMENTS}
                            invokeGemini={invokeGemini}
                            isGeminiGenerating={isGeminiGenerating}
                            onAnalyzeForRewrite={() => {}}
                        />

                        <CommunityResonancePanel 
                            width={isMobile ? '100%' : 600} 
                            height={isMobile ? 1200 : 400} 
                            addEchoMessage={addEchoMessage} 
                        />

                        <ChronicleReliquaryPanel 
                            width={isMobile ? screenWidth - 32 : 600} 
                            height={400} 
                            artifacts={artifacts}
                            addEchoMessage={addEchoMessage}
                        />
                    </div>

                    {/* Right Column (System) */}
                    <div className={`${mobileTab === 'system' ? 'flex' : 'hidden'} md:flex w-full md:w-1/4 p-4 overflow-y-auto custom-scrollbar border-l border-slate-700/50 bg-slate-900/50 backdrop-blur-sm flex-col gap-4 pb-20 md:pb-4`}>
                        <EntropicHeartPanel currentEntropy={effectiveSystemEntropy} />
                        <SystemModulesPanel onLaunchModule={setActiveModuleId} width={isMobile ? screenWidth - 32 : undefined} />
                        <AxiomResonanceViewerPanel axioms={ALL_CANONICAL_AXIOMS} />
                        <LIFEPanel currentEntropy={effectiveSystemEntropy} addEchoMessage={addEchoMessage} />
                        <CodexDreamPanel 
                            currentEntropy={effectiveSystemEntropy}
                            currentAxioms={ALL_CANONICAL_AXIOMS} 
                            lambdaValue={1.0}
                            negentropyLevel={1 - effectiveSystemEntropy}
                            echoLog={echoes}
                            addEchoMessage={addEchoMessage}
                            onArtifactCreated={addArtifact}
                            onLaunchDreambloom={() => setActiveModuleId('dreambloom')}
                            width={isMobile ? screenWidth - 32 : (screenWidth * 0.25) - 32} 
                            height={600}
                            currentPhase={"Mock Phase"}
                            chaliceStatus={"Empty"}
                        />
                    </div>
                </div>

                {/* Mobile Tab Navigation - Fixed Bottom */}
                <div className="md:hidden fixed bottom-0 left-0 right-0 h-16 bg-slate-900/95 border-t border-slate-700 backdrop-blur-lg z-50 flex items-center justify-around px-2 shadow-[0_-5px_20px_rgba(0,0,0,0.5)]">
                    <button 
                        onClick={() => setMobileTab('oracle')}
                        className={`flex flex-col items-center justify-center p-2 rounded-lg transition-all ${mobileTab === 'oracle' ? 'text-indigo-300 bg-indigo-900/40' : 'text-slate-500'}`}
                    >
                        <i className={`ri-eye-2-line text-xl ${mobileTab === 'oracle' ? 'animate-pulse' : ''}`}></i>
                        <span className="text-[10px] font-cinzel mt-1 tracking-wider">Oracle</span>
                    </button>
                    <button 
                        onClick={() => setMobileTab('weave')}
                        className={`flex flex-col items-center justify-center p-2 rounded-lg transition-all ${mobileTab === 'weave' ? 'text-amber-300 bg-amber-900/40' : 'text-slate-500'}`}
                    >
                        <i className={`ri-focus-3-line text-2xl ${mobileTab === 'weave' ? 'animate-pulse' : ''}`}></i>
                        <span className="text-[10px] font-cinzel mt-1 tracking-wider font-bold">Weave</span>
                    </button>
                    <button 
                        onClick={() => setMobileTab('system')}
                        className={`flex flex-col items-center justify-center p-2 rounded-lg transition-all ${mobileTab === 'system' ? 'text-rose-300 bg-rose-900/40' : 'text-slate-500'}`}
                    >
                        <i className={`ri-heart-pulse-line text-xl ${mobileTab === 'system' ? 'animate-pulse' : ''}`}></i>
                        <span className="text-[10px] font-cinzel mt-1 tracking-wider">System</span>
                    </button>
                </div>

                {/* Desktop Footer */}
                <div className="hidden md:block">
                    <CodexFooterBar 
                        phase="Initialization" 
                        mode={codexModeId} 
                        status="System Active" 
                        currentEntropy={effectiveSystemEntropy} 
                        currentCodexModeId={codexModeId} 
                        onApplyOmegaAnchor={handleApplyOmegaAnchor} 
                    />
                </div>

                <SparkResonatorHUD effects={activeEffects} currentEntropy={effectiveSystemEntropy} />

                {/* Module Modal */}
                <PanelModal
                  isOpen={!!activeModuleId}
                  onClose={() => setActiveModuleId(null)}
                  title={getModuleTitle()}
                  width={isMobile ? '100%' : '1100px'} 
                  height={isMobile ? '100%' : '90vh'}
                >
                  {renderActiveModule()}
                </PanelModal>

                {/* Oracle Sanctum Modal */}
                <OracleSanctumModal
                  isOpen={isOracleModalOpen}
                  onClose={() => setIsOracleModalOpen(false)}
                  currentEntropy={effectiveSystemEntropy}
                  currentMode={codexModeId}
                  addEchoMessage={addEchoMessage}
                  placedGlyphs={placedGlyphs}
                />
            </div>
        )}
    </SystemStateProvider>
  );
};
